<script setup lang="ts">
import {Bot,Send,UserRound,BookOpen,AlertCircle} from 'lucide-vue-next'
const prompt=ref('');const busy=ref(false)
const history=ref<{who:'bot'|'me';content:string;source?:string}[]>([{who:'bot',content:'Xin chào! Tôi là trợ lý hướng dẫn dựa trên các câu hỏi thường gặp (mô phỏng, chưa tích hợp mô hình AI RAG). Bạn muốn tìm hiểu thủ tục nào?'}])
const samples=['Nộp hồ sơ trực tuyến thế nào?','Cần chuẩn bị giấy tờ gì?','Tra cứu tiến độ hồ sơ ở đâu?']
async function send(text?:string){const q=(text||prompt.value).trim();if(q.length<5)return;history.value.push({who:'me',content:q});prompt.value='';busy.value=true;try{const response=await $fetch<{answer:string;source:string}>('/api/chat',{method:'POST',body:{message:q}});history.value.push({who:'bot',content:response.answer,source:response.source})}catch(e){history.value.push({who:'bot',content:readableError(e)})}finally{busy.value=false}}
</script>
<template><div class="space-y-4"><div class="flex items-center justify-between"><div><h2 class="text-xl font-black">Trợ lý hướng dẫn thủ tục</h2><p class="text-sm text-muted">Giải đáp từ kho FAQ mẫu và dẫn về nguồn hướng dẫn.</p></div><span class="rounded-full bg-violet-50 px-3 py-1.5 text-xs font-bold text-violet-700">FAQ demo · Chưa phải AI RAG</span></div>
 <section class="panel"><div class="scrollbar-hide max-h-[min(480px,60svh)] min-h-[260px] space-y-4 overflow-y-auto p-5"><div v-for="(m,index) in history" :key="index" :class="['flex gap-2',m.who==='me'?'flex-row-reverse':'']"><span :class="['grid h-9 w-9 shrink-0 place-items-center rounded-full',m.who==='bot'?'bg-blue-100 text-blue-700':'bg-green-100 text-green-700']"><Bot v-if="m.who==='bot'" :size="20"/><UserRound v-else :size="19"/></span><div :class="['max-w-[84%] rounded-2xl p-4 text-sm leading-relaxed',m.who==='bot'?'bg-blue-50':'bg-green-50']">{{m.content}}<NuxtLink v-if="m.source" :to="m.source" class="mt-2 flex items-center gap-1 font-bold text-brand-700"><BookOpen :size="14"/>Xem nguồn hướng dẫn →</NuxtLink></div></div><p v-if="busy" class="text-xs text-muted">Đang tìm trong câu hỏi mẫu...</p></div><div class="border-t p-4"><div class="mb-3 flex flex-wrap gap-2"><button v-for="s in samples" :key="s" class="rounded-full border border-blue-200 bg-blue-50 px-3 py-1.5 text-xs font-semibold text-brand-700 hover:bg-blue-100" @click="send(s)">{{s}}</button></div><form class="flex flex-wrap gap-2" @submit.prevent="send()"><input v-model="prompt" class="field min-w-0 flex-1" placeholder="Nhập câu hỏi của bạn..." minlength="5" maxlength="2000"/><button type="submit" :disabled="busy||prompt.trim().length<5" class="btn-primary"><Send :size="16"/> Gửi</button></form></div></section><p class="flex items-start gap-2 text-xs leading-relaxed text-amber-800"><AlertCircle :size="16" class="shrink-0"/>Câu trả lời chỉ để minh họa chức năng hướng dẫn, không thay thế tư vấn pháp lý hay thủ tục do cơ quan có thẩm quyền công bố.</p></div></template>
